'use strict';

const DEFAULT_DELIMITER = ',';
const DEFAULT_EOL = '\r\n';
const EOLS = ['\r\n', '\n'];

/** Short, safe description of a value for TypeError messages. */
function describe(value) {
  if (value === null) return 'null';
  if (Array.isArray(value)) return 'an array';
  switch (typeof value) {
    case 'string':
      return JSON.stringify(value);
    case 'number':
    case 'boolean':
    case 'bigint':
    case 'undefined':
      return `${typeof value} ${String(value)}`;
    case 'symbol':
      return value.toString();
    case 'function':
      return 'a function';
    default:
      return 'an object';
  }
}

function readOptions(options) {
  if (options === undefined) return {};
  if (options === null || typeof options !== 'object' || Array.isArray(options)) {
    throw new TypeError(`options must be an object, received ${describe(options)}`);
  }
  return options;
}

/**
 * Validates `options.delimiter`. "Single character" means one UTF-16 code
 * unit, the same unit columns are counted in.
 */
function resolveDelimiter(delimiter) {
  if (delimiter === undefined) return DEFAULT_DELIMITER;
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError(
      `delimiter must be a single character other than '"', CR or LF, received ${describe(delimiter)}`,
    );
  }
  return delimiter;
}

function resolveFlag(options, name) {
  const value = options[name];
  if (value === undefined) return false;
  if (typeof value !== 'boolean') {
    throw new TypeError(`${name} must be a boolean, received ${describe(value)}`);
  }
  return value;
}

function resolveEol(eol) {
  if (eol === undefined) return DEFAULT_EOL;
  if (!EOLS.includes(eol)) {
    throw new TypeError(`eol must be '\\r\\n' or '\\n', received ${describe(eol)}`);
  }
  return eol;
}

/**
 * Validates the stringify header. Duplicate names are rejected because
 * parse() rejects them in header mode, so the output could not be read back.
 */
function resolveHeader(header) {
  if (header === undefined || header === false) return null;
  if (!Array.isArray(header)) {
    throw new TypeError(`header must be an array of column names, received ${describe(header)}`);
  }
  if (header.length === 0) {
    throw new TypeError('header must contain at least one column name');
  }
  const seen = new Set();
  for (let i = 0; i < header.length; i++) {
    const name = header[i];
    if (typeof name !== 'string') {
      throw new TypeError(`header[${i}] must be a string, received ${describe(name)}`);
    }
    if (seen.has(name)) {
      throw new TypeError(`header[${i}] duplicates the column name ${JSON.stringify(name)}`);
    }
    seen.add(name);
  }
  return header.slice();
}

/** Normalized options for parse() and createParser(). Unknown keys are ignored. */
function parseOptions(options) {
  const opts = readOptions(options);
  return {
    delimiter: resolveDelimiter(opts.delimiter),
    header: resolveFlag(opts, 'header'),
    skipEmptyLines: resolveFlag(opts, 'skipEmptyLines'),
  };
}

/** Normalized options for stringify(). Unknown keys are ignored. */
function stringifyOptions(options) {
  const opts = readOptions(options);
  return {
    delimiter: resolveDelimiter(opts.delimiter),
    eol: resolveEol(opts.eol),
    header: resolveHeader(opts.header),
  };
}

module.exports = { describe, parseOptions, stringifyOptions };
'use strict';

const { csvError, UNCLOSED_QUOTE, INVALID_CLOSING_QUOTE } = require('./errors');
const { HeaderMapper } = require('./header');

const QUOTE = 0x22;
const LF = 0x0a;
const CR = 0x0d;
const BOM = 0xfeff;

// Scanner states.
const LINE_START = 0; // nothing read since the last line break or the start of input
const FIELD_START = 1; // just after a delimiter
const UNQUOTED = 2;
const QUOTED = 3;
const QUOTE_IN_QUOTED = 4; // a `"` inside a quoted field: the closing quote or the first half of `""`

/**
 * Incremental CSV scanner shared by parse() and createParser().
 *
 * Every code unit is examined once. Between chunks the scanner keeps only
 * its state, the current record's fields, the current field's text and
 * position counters, so memory and time stay proportional to the input.
 * Records are collected as their line break is read and handed out by
 * write() and end().
 */
class Parser {
  /**
   * @param {{delimiter: string, header: boolean, skipEmptyLines: boolean}} options
   *   already validated by parseOptions()
   */
  constructor(options) {
    this.delimiter = options.delimiter.charCodeAt(0);
    this.skipEmptyLines = options.skipEmptyLines;
    this.header = options.header ? new HeaderMapper() : null;

    this.state = LINE_START;
    this.fields = [];
    // Text of the current field read in earlier chunks or before an escaped quote.
    this.parts = [];
    this.records = [];

    this.started = false; // the first code unit (a possible BOM) has been seen
    this.pendingCR = false; // the last chunk ended with a CR; a leading LF completes the CRLF

    this.offset = 0; // absolute offset of the current chunk's first code unit
    this.line = 1;
    this.lineStart = 0; // absolute offset of the current line's first code unit
    this.recordLine = 1;
    this.fieldLine = 1;
    this.fieldColumn = 1;
  }

  /**
   * Scans a chunk and returns the records it completed.
   * @param {string} chunk
   * @returns {Array<string[] | Record<string, string>>}
   */
  write(chunk) {
    const length = chunk.length;
    if (length === 0) return this.take();
    let start = 0;
    if (!this.started) {
      this.started = true;
      if (chunk.charCodeAt(0) === BOM) {
        // Positions are reported as if the BOM were not there.
        start = 1;
        this.lineStart = 1;
      }
    }
    if (this.pendingCR) {
      this.pendingCR = false;
      if (chunk.charCodeAt(0) === LF) {
        // Skipped as a record terminator; inside a quoted field it stays in
        // the text because scan() slices from index 0.
        start = 1;
        this.lineStart = this.offset + 1;
      }
    }
    this.scan(chunk, start);
    this.offset += length;
    return this.take();
  }

  /**
   * Finishes the input and returns the last record, if any.
   * @returns {Array<string[] | Record<string, string>>}
   */
  end() {
    switch (this.state) {
      case FIELD_START:
        // The empty last field starts at the end of the input.
        this.fieldLine = this.line;
        this.fieldColumn = this.offset - this.lineStart + 1;
        this.endField('');
        this.endRecord();
        break;
      case UNQUOTED:
      case QUOTE_IN_QUOTED:
        this.endField(this.fieldText(''));
        this.endRecord();
        break;
      case QUOTED:
        throw csvError(UNCLOSED_QUOTE, 'Quoted field is never closed', this.fieldLine, this.fieldColumn);
      default:
        // LINE_START: no input, or it ended with a line break, which does not
        // start another record.
        break;
    }
    this.state = LINE_START;
    return this.take();
  }

  scan(chunk, start) {
    const length = chunk.length;
    const delimiter = this.delimiter;
    let state = this.state;
    // Start of the current field's text that has not been copied out yet.
    let segment = 0;

    for (let i = start; i < length; i++) {
      const c = chunk.charCodeAt(i);

      if (state === QUOTED) {
        if (c === QUOTE) {
          if (i > segment) this.parts.push(chunk.slice(segment, i));
          state = QUOTE_IN_QUOTED;
        } else if (c === CR || c === LF) {
          i = this.lineBreak(chunk, i, c);
        }
        continue;
      }

      if (state === UNQUOTED) {
        if (c === delimiter) {
          this.endField(this.fieldText(chunk.slice(segment, i)));
          state = FIELD_START;
        } else if (c === CR || c === LF) {
          this.endField(this.fieldText(chunk.slice(segment, i)));
          this.endRecord();
          i = this.lineBreak(chunk, i, c);
          state = LINE_START;
        }
        continue;
      }

      if (state === QUOTE_IN_QUOTED) {
        if (c === QUOTE) {
          // `""`: the second quote is kept as text.
          segment = i;
          state = QUOTED;
        } else if (c === delimiter) {
          this.endField(this.fieldText(''));
          state = FIELD_START;
        } else if (c === CR || c === LF) {
          this.endField(this.fieldText(''));
          this.endRecord();
          i = this.lineBreak(chunk, i, c);
          state = LINE_START;
        } else {
          throw csvError(
            INVALID_CLOSING_QUOTE,
            `Unexpected character ${JSON.stringify(String.fromCharCode(c))} after closing quote`,
            this.line,
            this.offset + i - this.lineStart + 1,
          );
        }
        continue;
      }

      // LINE_START or FIELD_START: a field begins at i.
      if (state === LINE_START) this.recordLine = this.line;
      this.fieldLine = this.line;
      this.fieldColumn = this.offset + i - this.lineStart + 1;

      if (c === QUOTE) {
        segment = i + 1;
        state = QUOTED;
      } else if (c === delimiter) {
        this.endField('');
        state = FIELD_START;
      } else if (c === CR || c === LF) {
        // After a delimiter this ends the record's last, empty field. At the
        // start of a line it is an empty line: one empty field, or skipped.
        if (state === FIELD_START || !this.skipEmptyLines) {
          this.endField('');
          this.endRecord();
        }
        i = this.lineBreak(chunk, i, c);
        state = LINE_START;
      } else {
        segment = i;
        state = UNQUOTED;
      }
    }

    if ((state === UNQUOTED || state === QUOTED) && length > segment) {
      this.parts.push(chunk.slice(segment, length));
    }
    this.state = state;
  }

  /**
   * Advances the position past the line break at i and returns the index of
   * its last code unit, so a CRLF is consumed as one break.
   */
  lineBreak(chunk, i, c) {
    this.line++;
    if (c === CR) {
      if (i + 1 === chunk.length) this.pendingCR = true;
      else if (chunk.charCodeAt(i + 1) === LF) i++;
    }
    this.lineStart = this.offset + i + 1;
    return i;
  }

  /** Joins the current field's saved text with `tail` and clears it. */
  fieldText(tail) {
    const parts = this.parts;
    if (parts.length === 0) return tail;
    if (tail !== '') parts.push(tail);
    const text = parts.length === 1 ? parts[0] : parts.join('');
    parts.length = 0;
    return text;
  }

  endField(value) {
    if (this.header !== null && this.header.columns === null) {
      this.header.addName(value, this.fieldLine, this.fieldColumn);
    }
    this.fields.push(value);
  }

  endRecord() {
    const fields = this.fields;
    this.fields = [];
    if (this.header === null) {
      this.records.push(fields);
      return;
    }
    const record = this.header.toRecord(fields, this.recordLine);
    if (record !== null) this.records.push(record);
  }

  take() {
    const records = this.records;
    this.records = [];
    return records;
  }
}

module.exports = { Parser };
'use strict';

/**
 * Error thrown for malformed CSV input.
 *
 * `line` and `column` are 1-based. Lines are counted by CRLF, LF and CR,
 * including those inside quoted fields. Columns count UTF-16 code units, and a
 * leading byte order mark does not occupy a column.
 */
class CsvError extends Error {
  /**
   * @param {string} message
   * @param {number} line
   * @param {number} column
   * @param {string} [code] UNCLOSED_QUOTE, INVALID_CLOSING_QUOTE,
   *   DUPLICATE_HEADER or FIELD_COUNT_MISMATCH when thrown by the parser.
   */
  constructor(message, line, column, code) {
    super(message);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
    this.code = code;
  }
}

// Values of CsvError#code; the README lists the position each one reports.
const UNCLOSED_QUOTE = 'UNCLOSED_QUOTE';
const INVALID_CLOSING_QUOTE = 'INVALID_CLOSING_QUOTE';
const DUPLICATE_HEADER = 'DUPLICATE_HEADER';
const FIELD_COUNT_MISMATCH = 'FIELD_COUNT_MISMATCH';

/** Builds a CsvError whose message ends with the position it reports. */
function csvError(code, description, line, column) {
  return new CsvError(`${description} at line ${line}, column ${column}`, line, column, code);
}

module.exports = {
  CsvError,
  csvError,
  UNCLOSED_QUOTE,
  INVALID_CLOSING_QUOTE,
  DUPLICATE_HEADER,
  FIELD_COUNT_MISMATCH,
};
'use strict';

const { csvError, DUPLICATE_HEADER, FIELD_COUNT_MISMATCH } = require('./errors');

/**
 * Header mode: takes the first record as column names and turns every later
 * record into an object keyed by them.
 */
class HeaderMapper {
  constructor() {
    /** @type {string[] | null} null until the header record has ended. */
    this.columns = null;
    this.seen = new Set();
  }

  /**
   * Called as each header field ends, so a duplicate is reported before any
   * error that appears later in the header record.
   */
  addName(name, line, column) {
    if (this.seen.has(name)) {
      throw csvError(DUPLICATE_HEADER, `Duplicate header name ${JSON.stringify(name)}`, line, column);
    }
    this.seen.add(name);
  }

  /**
   * Returns the record as an object, or null for the header record itself.
   * @param {string[]} fields
   * @param {number} line the line the record starts on
   */
  toRecord(fields, line) {
    const columns = this.columns;
    if (columns === null) {
      this.columns = fields;
      this.seen = null;
      return null;
    }
    if (fields.length !== columns.length) {
      throw csvError(
        FIELD_COUNT_MISMATCH,
        `Record has ${fields.length} field${fields.length === 1 ? '' : 's'} but the header has ${columns.length}`,
        line,
        1,
      );
    }
    const record = {};
    for (let i = 0; i < columns.length; i++) {
      const name = columns[i];
      if (name === '__proto__') {
        // Plain assignment would call the Object.prototype setter and drop the value.
        Object.defineProperty(record, name, {
          value: fields[i],
          enumerable: true,
          writable: true,
          configurable: true,
        });
      } else {
        record[name] = fields[i];
      }
    }
    return record;
  }
}

module.exports = { HeaderMapper };
'use strict';

const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv');

/** Deterministic PRNG (mulberry32) so fuzz failures can be replayed from the seed. */
function random(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function errorSummary(err) {
  assert.ok(err instanceof CsvError, `expected a CsvError, got ${err && err.stack}`);
  return { error: { line: err.line, column: err.column, code: err.code, message: err.message } };
}

/** parse() result as `{records}` or `{error}` so success and failure compare alike. */
function parseOutcome(text, options) {
  try {
    return { records: parse(text, options) };
  } catch (err) {
    return errorSummary(err);
  }
}

/** Feeds chunks to a fresh createParser() and returns the same shape as parseOutcome. */
function streamOutcome(chunks, options) {
  const parser = createParser(options);
  const records = [];
  try {
    for (const chunk of chunks) {
      for (const record of parser.write(chunk)) records.push(record);
    }
    for (const record of parser.end()) records.push(record);
    return { records };
  } catch (err) {
    return errorSummary(err);
  }
}

/** Splits text at the given ascending indices. */
function splitAt(text, points) {
  const chunks = [];
  let from = 0;
  for (const point of points) {
    chunks.push(text.slice(from, point));
    from = point;
  }
  chunks.push(text.slice(from));
  return chunks;
}

/** Splits text into chunks of random length (including empty chunks). */
function randomChunks(text, rand, maxLength = 5) {
  const chunks = [];
  let from = 0;
  while (from < text.length) {
    const size = Math.floor(rand() * (maxLength + 1));
    chunks.push(text.slice(from, from + size));
    from += size;
  }
  return chunks;
}

module.exports = { random, parseOutcome, streamOutcome, splitAt, randomChunks };
# csv-rfc4180

A CSV parser, streaming parser and serializer for Node.js. It has no dependencies and uses CommonJS.

```js
const { parse, createParser, stringify, CsvError } = require('./src/csv');

parse('name,qty\r\n"Widget, large",3\r\n');
// [['name', 'qty'], ['Widget, large', '3']]

parse('name,qty\nbolt,10\n', { header: true });
// [{ name: 'bolt', qty: '10' }]

stringify([['name', 'note'], ['bolt', 'says "hi"']]);
// 'name,note\r\nbolt,"says ""hi"""\r\n'
```

Run the tests with `npm test`. They use the built-in `node:test` runner.

## API

### `parse(text, options?)`

Returns an array of records. Each record is an array of strings, or an object when `header` is `true`.

| Option | Default | Meaning |
| --- | --- | --- |
| `delimiter` | `','` | Field separator. Must be one character (one UTF-16 code unit) other than `"`, CR or LF. |
| `header` | `false` | Use the first record as column names and return objects. |
| `skipEmptyLines` | `false` | Drop lines that contain nothing at all. |

Parsing rules:

- Records end at CRLF, LF or CR, and one input may mix them. A single line break at the very end of the input does not start another record.
- An empty line is the record `['']` unless `skipEmptyLines` is set. A line holding `""` or a lone delimiter is not empty.
- A field that starts with `"` is quoted. Inside it, delimiters and line breaks are literal and `""` is one `"`. The closing quote must be followed by a delimiter, a line break or the end of input.
- A `"` anywhere else in a field is an ordinary character. Fields are never trimmed.
- A leading byte order mark (U+FEFF) is dropped.
- In header mode, duplicate column names and records whose field count differs from the header's are errors. An input with only a header returns `[]`.

`parse` throws a `TypeError` when `text` is not a string or an option is invalid. It throws a `CsvError` when the input is malformed.

### `createParser(options?)`

Returns `{ write(chunk), end() }` for input that arrives in pieces. It takes the same options as `parse`.

- `write(chunk)` takes a string and returns the records that the chunk completed. A record is returned by the call whose chunk contains the line break that ends it.
- `end()` returns the last record, if the input did not end with a line break.
- After `end()`, or after either method throws, both methods throw an `Error`.

Chunks can be split anywhere: between CR and LF, inside a quoted field, or between the two quotes of `""`. The records and any `CsvError` are the same as `parse` gives for the concatenated input. Each code unit is read once, so the total work is linear in the input size.

To parse a file stream, decode it to strings first so multi-byte characters are never split:

```js
const fs = require('node:fs');

async function readCsv(path) {
  const parser = createParser({ header: true });
  const stream = fs.createReadStream(path, { encoding: 'utf8' });
  const records = [];
  for await (const chunk of stream) {
    for (const record of parser.write(chunk)) records.push(record);
  }
  for (const record of parser.end()) records.push(record);
  return records;
}
```

### `stringify(rows, options?)`

Serializes an array of records to CSV text.

| Option | Default | Meaning |
| --- | --- | --- |
| `delimiter` | `','` | Validated as in `parse`. |
| `eol` | `'\r\n'` | Record separator, `'\r\n'` or `'\n'`. The output also ends with one `eol`. |
| `header` | none | Array of column names. The header row is written first, and rows may be objects. |

- Strings are written as they are, numbers and booleans through `String()`, and `null` and `undefined` as empty fields. Any other value throws a `TypeError`.
- A field is quoted when it contains the delimiter, `"`, CR or LF, or when it starts or ends with a space. Quotes inside are doubled.
- A record whose only field is empty is written as `""`, so it is not read back as an empty line.
- For object rows, each header column takes the object's own property of that name. A missing key becomes an empty field and extra keys are ignored. Array rows are still accepted with `header` and are written positionally.
- `stringify([])` returns `''`.

For any rows that are non-empty arrays of strings, `parse(stringify(rows, opts), opts)` returns the same rows, with or without `skipEmptyLines`.

### `CsvError`

A subclass of `Error` with these properties:

- `line`: 1-based line number. Lines are counted by the line breaks above, including those inside quoted fields.
- `column`: 1-based column in UTF-16 code units.
- `code`: the reason, as one of the strings below.

| `code` | Reported position |
| --- | --- |
| `UNCLOSED_QUOTE` | The opening `"` of a quoted field that is never closed. |
| `INVALID_CLOSING_QUOTE` | The character after a closing `"` that is not a delimiter or line break. |
| `DUPLICATE_HEADER` | Where the second field with the same name starts. |
| `FIELD_COUNT_MISMATCH` | Column 1 of the line where the record starts. |

When the input has several errors, the first one a left-to-right read reaches is thrown. A header name is checked when its field ends, and a record's field count is checked when the record ends.

## Decisions on unspecified behaviour

- **Positions after a BOM.** The BOM is ignored, so it takes up no column. In `﻿"a"x` the `x` is at column 4.
- **Multi-line records.** A field count error reports the line the record starts on, which matters when a quoted field spans lines.
- **Header name checks happen at field end.** `a,a,"b` (unclosed) reports the duplicate at column 3, because that field ends before the input does. `a,"a"x` reports the `x`, because the second field never ended.
- **Empty lines in header mode are records.** Without `skipEmptyLines`, a blank line is a one-field record and fails the count check unless the header has one column.
- **`__proto__` as a column name** becomes an ordinary own property. Records are still plain objects, so `assert.deepStrictEqual` against literals works.
- **Strict options.** `options` must be an object if given, and `header` and `skipEmptyLines` must be booleans in `parse`. Unknown keys are ignored, so one options object can be shared between `parse` and `stringify`, as the round-trip guarantee needs.
- **Stringify header validation.** `header` must be a non-empty array of unique strings, or `false`/`undefined` for none. Duplicates are rejected because `parse` would reject the output.
- **Header with no rows.** `stringify([], { header: ['a', 'b'] })` returns `'a,b\r\n'`, which parses back in header mode to `[]`.
- **Leading BOM in output.** If the output would start with U+FEFF, because the first field starts with one or because it is empty and the delimiter is U+FEFF, that field is quoted. Otherwise `parse` would drop the character and the round trip would fail.
- **Empty records.** `stringify([[]])` writes an empty line. It reads back as `['']`, or nothing with `skipEmptyLines`. The round-trip guarantee only covers non-empty records.

