    this.skipEmptyLines = options.skipEmptyLines;
    this.header = options.header ? new HeaderMapper() : null;

    this.state = LINE_START;
    this.fields = [];
    // Text of the current field read in earlier chunks or before an escaped quote.
    this.parts = [];
    this.records = [];

    this.started = false; // the first code unit (a possible BOM) has been seen
    this.pendingCR = false; // the last chunk ended with a CR; a leading LF completes the CRLF

    this.offset = 0; // absolute offset of the current chunk's first code unit
    this.line = 1;
    this.lineStart = 0; // absolute offset of the current line's first code unit
    this.recordLine = 1;
    this.fieldLine = 1;
    this.fieldColumn = 1;
