  scan(chunk, start) {
    const length = chunk.length;
    const delimiter = this.delimiter;
    let state = this.state;
    // Start of the current field's text that has not been copied out yet.
    let segment = 0;

    for (let i = start; i < length; i++) {
      const c = chunk.charCodeAt(i);

      if (state === QUOTED) {
