const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv');

/** Deterministic PRNG (mulberry32) so fuzz failures can be replayed from the seed. */
function random(seed) {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
