    ['removes spaces and tabs from both ends of unquoted fields', ' a \t, \tb c\t ,d', [['a', 'b c', 'd']]],
    ['turns a blank field into an empty one', 'a, \t ,b', [['a', '', 'b']]],
    ['trims the last field at the end of input', 'a, b ', [['a', 'b']]],
    ['trims before every kind of line break', ' a \r\n b \n c \r d ', [['a'], ['b'], ['c'], ['d']]],
    ['keeps other whitespace', ' a ,\fb\v', [[' a ', '\fb\v']]],
    ['ignores blanks before the opening quote', '  "a",\t"b"', [['a', 'b']]],
    ['ignores blanks after the closing quote', '"a"  ,"b"\t\t', [['a', 'b']]],
    ['ignores blanks around a quoted field before a line break', ' "a" \r\n\t"b"\t\n', [['a'], ['b']]],
